using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using MarketSphere.Domain.Entities.Infrastructure;
namespace MarketSphere.Infrastructure.Persistence.Configurations.Infrastructure;
public sealed class FileAttachmentConfiguration : IEntityTypeConfiguration<FileAttachment> { public void Configure(EntityTypeBuilder<FileAttachment> builder) { builder.ToTable("FileAttachments", t => t.HasCheckConstraint("CK_FileAttachments_Size", "[FileSizeBytes] > 0")); builder.HasKey(x => x.FileAttachmentID); builder.Property(x => x.ReferenceType).HasMaxLength(100).IsRequired(); builder.Property(x => x.AttachmentCategory).HasMaxLength(100).IsRequired(); builder.Property(x => x.FileName).HasMaxLength(260).IsRequired(); builder.Property(x => x.StoredFileName).HasMaxLength(500).IsRequired(); builder.Property(x => x.FileUrl).HasMaxLength(1000).IsRequired(); builder.Property(x => x.MimeType).HasMaxLength(200).IsRequired(); builder.Property(x => x.FileHash).HasMaxLength(128).IsRequired(); builder.Property(x => x.GPS).HasMaxLength(100); builder.Property(x => x.VerificationStatus).HasConversion<int>(); builder.HasIndex(x => new { x.ReferenceType, x.ReferenceID, x.AttachmentCategory }); builder.HasIndex(x => x.StoredFileName).IsUnique(); builder.HasIndex(x => x.FileHash); builder.HasOne(x => x.VerifiedByUser).WithMany().HasForeignKey(x => x.VerifiedByUserID).OnDelete(DeleteBehavior.Restrict); builder.HasOne(x => x.UploadedByUser).WithMany().HasForeignKey(x => x.UploadedByUserID).OnDelete(DeleteBehavior.Restrict); } }
